class StorageManager:
    """Storage manager for HSE documents - Handles saving, retrieving, and managing documents"""
    
    def __init__(self, base_dir=None):
        """
        Initialize the storage manager
        
        Args:
            base_dir: Base directory for storing documents (default: 'hse_documents' in current directory)
        """
        import os
        from pathlib import Path
        import json
        import shutil
        from datetime import datetime
        
        if base_dir is None:
            # Default to hse_documents folder in the backend directory
            base_dir = os.path.join(os.path.dirname(__file__), 'hse_documents')
        
        self.base_dir = Path(base_dir)
        self.temp_dir = self.base_dir / 'temp'
        self.exports_dir = self.base_dir / 'exports'
        self.metadata_dir = self.base_dir / 'metadata'
        
        # Create all necessary directories
        self._ensure_directories()
        
        print(f"\n📁 Storage Manager Initialized")
        print(f"   Base directory: {self.base_dir}")
        print(f"   Exports: {self.exports_dir}")
        print(f"   Metadata: {self.metadata_dir}")
        print(f"   Temp: {self.temp_dir}")
    
    def _ensure_directories(self):
        """Create all required directories if they don't exist"""
        for directory in [self.base_dir, self.temp_dir, self.exports_dir, self.metadata_dir]:
            directory.mkdir(parents=True, exist_ok=True)
    
    def save_export(self, document_id, content, format_type, metadata=None):
        """
        Save a document export to storage
        
        Args:
            document_id: Unique document identifier
            content: Document content (bytes or string)
            format_type: Format type (html, pdf, docx, txt, etc.)
            metadata: Optional metadata dictionary
        
        Returns:
            str: Path to the saved file
        """
        # Clean document_id (remove any invalid characters)
        clean_id = self._clean_filename(document_id)
        
        # Determine file extension
        extension = self._get_extension(format_type)
        filename = f"{clean_id}{extension}"
        filepath = self.exports_dir / filename
        
        # Save content
        if isinstance(content, str):
            content = content.encode('utf-8')
        
        with open(filepath, 'wb') as f:
            f.write(content)
        
        # Save metadata if provided
        if metadata:
            self._save_metadata(clean_id, {
                **metadata,
                'format': format_type,
                'filename': filename,
                'file_size': len(content),
                'saved_at': datetime.now().isoformat()
            })
        
        # Create a symlink or copy to main directory for easy access
        main_filepath = self.base_dir / filename
        if not main_filepath.exists():
            try:
                import shutil
                shutil.copy2(filepath, main_filepath)
            except:
                pass  # Ignore if we can't create the link
        
        print(f"✅ Document saved: {filepath}")
        return str(filepath)
    
    def get_document_path(self, filename):
        """
        Get the full path for a document
        
        Args:
            filename: The filename to look for
        
        Returns:
            str: Full path if file exists, None otherwise
        """
        # Check in exports first
        filepath = self.exports_dir / filename
        if filepath.exists():
            return str(filepath)
        
        # Check in base directory
        filepath = self.base_dir / filename
        if filepath.exists():
            return str(filepath)
        
        return None
    
    def get_document(self, document_id, format_type=None):
        """
        Retrieve a document from storage
        
        Args:
            document_id: Document identifier
            format_type: Optional format type (if not specified, tries to find any)
        
        Returns:
            bytes: Document content or None if not found
        """
        clean_id = self._clean_filename(document_id)
        
        if format_type:
            # Try specific format
            extension = self._get_extension(format_type)
            filepath = self._find_file(clean_id, extension)
            if filepath and filepath.exists():
                with open(filepath, 'rb') as f:
                    return f.read()
        else:
            # Try to find any file with this ID
            for ext in ['.html', '.pdf', '.docx', '.txt', '.json']:
                filepath = self._find_file(clean_id, ext)
                if filepath and filepath.exists():
                    with open(filepath, 'rb') as f:
                        return f.read()
        
        return None
    
    def get_document_info(self, document_id):
        """
        Get information about a document
        
        Args:
            document_id: Document identifier
        
        Returns:
            dict: Document information or None
        """
        clean_id = self._clean_filename(document_id)
        
        # Try to get metadata first
        metadata = self._load_metadata(clean_id)
        if metadata:
            return metadata
        
        # If no metadata, scan for files
        files = []
        for ext in ['.html', '.pdf', '.docx', '.txt']:
            filepath = self._find_file(clean_id, ext)
            if filepath and filepath.exists():
                stat = filepath.stat()
                files.append({
                    'format': ext[1:],  # Remove the dot
                    'filename': filepath.name,
                    'size': stat.st_size,
                    'modified': datetime.fromtimestamp(stat.st_mtime).isoformat()
                })
        
        if files:
            return {
                'document_id': clean_id,
                'files': files,
                'formats': [f['format'] for f in files]
            }
        
        return None
    
    def list_documents(self, format_type=None, limit=100):
        """
        List all documents in storage
        
        Args:
            format_type: Optional filter by format
            limit: Maximum number of documents to return
        
        Returns:
            list: List of document information
        """
        documents = []
        
        pattern = f"*{self._get_extension(format_type)}" if format_type else "*.*"
        
        for filepath in self.exports_dir.glob(pattern):
            if filepath.is_file():
                stat = filepath.stat()
                doc_id = filepath.stem  # Filename without extension
                
                # Try to get metadata
                metadata = self._load_metadata(doc_id)
                
                documents.append({
                    'id': doc_id,
                    'filename': filepath.name,
                    'format': filepath.suffix[1:],  # Remove the dot
                    'size': stat.st_size,
                    'created': datetime.fromtimestamp(stat.st_ctime).isoformat(),
                    'modified': datetime.fromtimestamp(stat.st_mtime).isoformat(),
                    'metadata': metadata
                })
        
        # Sort by modified date (newest first) and limit
        documents.sort(key=lambda x: x['modified'], reverse=True)
        return documents[:limit]
    
    def delete_document(self, document_id, format_type=None):
        """
        Delete a document from storage
        
        Args:
            document_id: Document identifier
            format_type: Optional specific format to delete (if None, deletes all)
        
        Returns:
            bool: True if deleted, False otherwise
        """
        clean_id = self._clean_filename(document_id)
        deleted = False
        
        if format_type:
            # Delete specific format
            extension = self._get_extension(format_type)
            filepath = self._find_file(clean_id, extension)
            if filepath and filepath.exists():
                filepath.unlink()
                deleted = True
        else:
            # Delete all files with this ID
            for ext in ['.html', '.pdf', '.docx', '.txt']:
                filepath = self._find_file(clean_id, ext)
                if filepath and filepath.exists():
                    filepath.unlink()
                    deleted = True
            
            # Delete metadata
            metadata_file = self.metadata_dir / f"{clean_id}.json"
            if metadata_file.exists():
                metadata_file.unlink()
        
        return deleted
    
    def save_document(self, content, filename, doc_type=None, metadata=None):
        """
        Save a document to storage (alias for save_export)
        
        Args:
            content: The document content (bytes or string)
            filename: The filename to save as
            doc_type: Optional document type
            metadata: Optional metadata dictionary
        
        Returns:
            str: The full path where the document was saved
        """
        import os
        
        # Extract document_id from filename
        document_id = os.path.splitext(filename)[0]
        
        # Determine format from extension
        ext = os.path.splitext(filename)[1].lower()
        format_map = {
            '.html': 'html',
            '.htm': 'html',
            '.pdf': 'pdf',
            '.docx': 'docx',
            '.doc': 'docx',
            '.txt': 'txt',
            '.json': 'json'
        }
        format_type = format_map.get(ext, 'unknown')
        
        # Use save_export to do the actual saving
        return self.save_export(document_id, content, format_type, metadata)
    
    def _save_metadata(self, document_id, metadata):
        """Save metadata for a document"""
        metadata_file = self.metadata_dir / f"{document_id}.json"
        with open(metadata_file, 'w') as f:
            import json
            json.dump(metadata, f, indent=2, default=str)
    
    def _load_metadata(self, document_id):
        """Load metadata for a document"""
        metadata_file = self.metadata_dir / f"{document_id}.json"
        if metadata_file.exists():
            with open(metadata_file, 'r') as f:
                import json
                return json.load(f)
        return None
    
    def _find_file(self, document_id, extension):
        """Find a file in exports or base directory"""
        # Check exports first
        filepath = self.exports_dir / f"{document_id}{extension}"
        if filepath.exists():
            return filepath
        
        # Check base directory
        filepath = self.base_dir / f"{document_id}{extension}"
        if filepath.exists():
            return filepath
        
        return None
    
    def _clean_filename(self, filename):
        """Clean filename to remove invalid characters"""
        # Remove any path separators and invalid characters
        invalid_chars = '<>:"/\\|?*'
        for char in invalid_chars:
            filename = filename.replace(char, '_')
        return filename[:100]  # Limit length
    
    def _get_extension(self, format_type):
        """Get file extension for format type"""
        format_map = {
            'html': '.html',
            'htm': '.html',
            'pdf': '.pdf',
            'docx': '.docx',
            'doc': '.docx',
            'txt': '.txt',
            'text': '.txt',
            'json': '.json',
            'xml': '.xml',
            'csv': '.csv'
        }
        return format_map.get(format_type.lower(), f".{format_type.lower()}")
    
    def get_storage_stats(self):
        """Get storage statistics"""
        total_size = 0
        file_count = 0
        formats = {}
        
        for filepath in self.exports_dir.glob("*.*"):
            if filepath.is_file():
                stat = filepath.stat()
                total_size += stat.st_size
                file_count += 1
                
                ext = filepath.suffix.lower()
                formats[ext] = formats.get(ext, 0) + 1
        
        return {
            'total_files': file_count,
            'total_size_bytes': total_size,
            'total_size_mb': round(total_size / (1024 * 1024), 2),
            'formats': formats,
            'exports_dir': str(self.exports_dir),
            'metadata_dir': str(self.metadata_dir)
        }

    def create_temp_file(self, content, suffix='.tmp'):
        """
        Create a temporary file
        
        Args:
            content: File content
            suffix: File suffix
        
        Returns:
            str: Path to temporary file
        """
        import tempfile
        
        with tempfile.NamedTemporaryFile(mode='wb', suffix=suffix, delete=False, dir=self.temp_dir) as f:
            if isinstance(content, str):
                content = content.encode('utf-8')
            f.write(content)
            return f.name

    def cleanup_temp_files(self, max_age_hours=24):
        """
        Clean up old temporary files
        
        Args:
            max_age_hours: Maximum age of files to keep (in hours)
        """
        import time
        
        current_time = time.time()
        max_age_seconds = max_age_hours * 3600
        
        for filepath in self.temp_dir.glob("*"):
            if filepath.is_file():
                file_age = current_time - filepath.stat().st_mtime
                if file_age > max_age_seconds:
                    filepath.unlink()
                    print(f"🧹 Cleaned up temp file: {filepath}")

class HSEHTMLStylist:
    """
    DEDICATED HTML STYLING CLASS
    Different styles for different:
    - Industries (Construction, Oil & Gas, Healthcare, etc.)
    - Document Types (Permit, Risk Assessment, Incident Report, etc.)
    - International Standards (OSHA, HSE UK, EU, ISO, etc.)
    - Table Types (Risk Matrix, Permit Form, Checklist, etc.)
    
    This class ONLY provides styling - document structure comes from generators
    """
    
    # ========================================================================
    # INITIALIZATION
    # ========================================================================
    
    def __init__(self, hub=None):
        # Initialize debug log first
        self.debug_log = []
        
        # Import industry enum
        from app import Industry as LocalIndustry
        self.Industry = LocalIndustry
        self.hub = hub  # Store hub reference for template access
        
        self._log_init_status()
        self._log('init_start', {
            'hub_provided': hub is not None,
            'industry_enum_loaded': self.Industry is not None
        })
        
        self._initialize_all_styles()
        
        self._log('init_complete', {
            'industries_loaded': len(self.industry_colors) if hasattr(self, 'industry_colors') else 0,
            'standards_loaded': len(self.standard_styles) if hasattr(self, 'standard_styles') else 0
        })
    
    def _log_init_status(self):
        """Log initialization status"""
        print("\n" + "="*80)
        print("🔧 HSEHTMLStylist INITIALIZING")
        print("="*80)
        print(f"Hub provided: {self.hub is not None}")
        print("="*80 + "\n")
    
    def _log(self, step, data=None):
        """Internal debug logging"""
        from datetime import datetime
        entry = {
            'step': step,
            'timestamp': datetime.now().isoformat(),
            'data': data
        }
        self.debug_log.append(entry)
        print(f"\n🔍 STYLIST DEBUG [{step}]: {data if data else ''}")
    
    # ========================================================================
    # STYLE INITIALIZATION
    # ========================================================================
    
    def _initialize_all_styles(self):
        """Initialize all style collections"""
        
        self._log('initialize_styles_started', {
            'industry_enum': str(self.Industry) if self.Industry else None,
            'has_energy': hasattr(self.Industry, 'ENERGY') if self.Industry else False
        })
        
        self._debug_industry_enum()
        self._initialize_industry_colors()
        self._initialize_standard_styles()
        self._initialize_table_styles()
        
        self._log('initialize_styles_completed', {
            'industries_loaded': len(self.industry_colors),
            'standards_loaded': len(self.standard_styles)
        })
    
    def _debug_industry_enum(self):
        """Debug industry enum"""
        print("\n" + "="*80)
        print("🔍 HSEHTMLStylist DEBUG - Using CORRECT Industry Enum")
        print("="*80)
        print(f"Industry enum: {self.Industry}")
        print(f"Has ENERGY: {hasattr(self.Industry, 'ENERGY') if self.Industry else False}")
        if self.Industry and hasattr(self.Industry, 'ENERGY'):
            print(f"ENERGY value: {self.Industry.ENERGY.value}")
        print("="*80 + "\n")
    
