class ConfigurationSystemInitializer:

    def _initialize_configuration_systems(self):
        """Initialize all configuration systems"""
        self.industry_templates = self._initialize_international_industries()
        self.document_type_templates = self._initialize_comprehensive_document_types()
        self.international_standards = self._initialize_international_standards()
        self.industry_colors = self._initialize_industry_colors()
        self.document_type_colors = self._initialize_document_type_colors()
        self.model_configs = self._initialize_model_configs()
        self.document_templates = self._initialize_document_templates()
        self.industry_knowledge = self._load_enhanced_industry_knowledge()
        
        # Initialize specialized templates
        self.construction_specialized = ConstructionSpecializedTemplates()
        self.healthcare_specialized = HealthcareSpecializedTemplates()
        self.manufacturing_specialized = ManufacturingSpecializedTemplates()
        self.aviation_specialized = AviationSpecializedTemplates()
        self.emergency_templates = EmergencyResponseTemplates()
        self.incident_templates = IncidentManagementTemplates()
        self.inspection_templates = InspectionMonitoringTemplates()
        self.operational_templates = OperationalSafetyTemplates()
        self.management_templates = SafetyManagementTemplates()
        self.contractor_templates = ContractorManagementTemplates()
        self.environmental_templates = EnvironmentalTemplates()
        self.health_templates = HealthHygieneTemplates()
        self.equipment_templates = EquipmentSafetyTemplates()
        
        # Initialize industry-specific generators
        self.industry_generators = {
            'construction': EnhancedConstructionPermitGenerator(),
            'oil_gas': EnhancedOilGasPermitGenerator(),
            'healthcare': EnhancedHealthcarePermitGenerator(),
            'manufacturing': EnhancedManufacturingPermitGenerator(),
            'mining': EnhancedMiningPermitGenerator(),
            'aviation': EnhancedAviationPermitGenerator(),
            'maritime': EnhancedMaritimePermitGenerator(),
            'chemical': EnhancedChemicalPermitGenerator(),
            'energy': EnhancedEnergyPermitGenerator(),
            'transportation': EnhancedTransportationPermitGenerator(),
            'pharmaceutical': EnhancedPharmaceuticalPermitGenerator(),
            'food_beverage': EnhancedFoodBeveragePermitGenerator(),
            'education': EnhancedEducationPermitGenerator(),
            'hospitality': EnhancedHospitalityPermitGenerator(),
            'retail': EnhancedRetailPermitGenerator(),
            'telecom': EnhancedTelecomPermitGenerator(),
            'general': EnhancedGeneralPermitGenerator()
        }
    
    

