def register_general_safety_documents():
    """Register the general safety documents with the system"""
    return GeneralSafetyDocuments()

class HTMLTemplateEngineCompatibility:
    """Compatibility layer for existing code expecting html_template_engine"""
    
    def __init__(self, hub):
        self.hub = hub
        self.styles = {
            'professional': 'Professional Blue Theme',
            'modern': 'Modern Clean Theme',
            'classic': 'Classic Formal Theme',
            'minimal': 'Minimal Light Theme'
        }
        self.categories = {
            'safety': ['safety_plan', 'safety_procedure', 'safety_manual'],
            'compliance': ['permit', 'risk_assessment', 'audit_report'],
            'training': ['training_record', 'training_certificate', 'orientation_checklist'],
            'general': ['general_document', 'report', 'memo']
        }
        self.templates = {}  # Add this
        self.storage_manager = self.StorageManagerCompat(hub)
        
        # Initialize templates from hub
        self._load_templates_from_hub()
    
    def _load_templates_from_hub(self):
        """Load templates from the hub"""
        # Get all permits
        permits = self.hub.get_available_permits()
        for permit in permits:
            template_id = permit['id']
            self.templates[template_id] = {
                'id': template_id,
                'name': permit['name'],
                'industry': permit['industry'],
                'type': 'permit'
            }
        
        # Get all risk assessments
        risks = self.hub.get_available_risk_assessments()
        for risk in risks:
            template_id = risk['id']
            self.templates[template_id] = {
                'id': template_id,
                'name': risk['name'],
                'industry': risk['industry'],
                'type': 'risk_assessment'
            }
    
    def get_template_list(self):
        """Get all available templates - compatibility method"""
        templates = []
        
        # Get all permit templates from hub
        permits = self.hub.get_available_permits()
        for permit in permits:
            templates.append({
                'id': permit['id'],
                'name': permit['name'].replace('_', ' ').title(),
                'category': 'permit',
                'industry': permit['industry'],
                'type': 'permit'
            })
        
        # Get all risk assessments from hub
        risks = self.hub.get_available_risk_assessments()
        for risk in risks:
            templates.append({
                'id': risk['id'],
                'name': f"Risk Assessment - {risk['industry'].title()}",
                'category': 'risk_assessment',
                'industry': risk['industry'],
                'type': 'risk_assessment'
            })
        
        return templates
    
    def generate_document(self, doc_type: str, data: Dict, style: str = 'professional'):
        """Generate document - compatibility method"""
        industry = data.get('industry', 'general')
        
        # Generate document using hub
        result = self.hub.generate_document(
            industry=industry,
            document_type=doc_type,
            template_name=doc_type if doc_type != 'general' else None,
            format='html',
            reference=data.get('reference'),
            **data
        )
        
        if result['success']:
            return result.get('formatted_content', result.get('content', ''))
        
        return f"<html><body><h1>Document Generation Failed</h1><p>{result.get('errors', ['Unknown error'])[0]}</p></body></html>"
    
    def generate_pdf(self, html_content: str, metadata: Dict = None):
        """Generate PDF - compatibility stub"""
        try:
            import weasyprint
            pdf = weasyprint.HTML(string=html_content).write_pdf()
            return pdf
        except ImportError:
            return html_content.encode('utf-8')
    
    def export_document(self, html_content: str, export_format: str, metadata: Dict = None):
        """Export document - compatibility stub"""
        return html_content.encode('utf-8')
    
    def cleanup(self, days_old: int = 30):
        """Cleanup storage - compatibility method"""
        return {'cleaned': 0, 'space_freed': 0}
    
    def get_storage_stats(self):
        """Get storage stats - compatibility method"""
        return {
            'total_documents': len(self.hub.templates),
            'storage_used': '0 MB',
            'storage_path': str(Path.cwd() / 'hse_documents')
        }
    
    class StorageManagerCompat:
        """Compatibility storage manager"""
        def __init__(self, hub):
            self.hub = hub
            self.storage_path = Path.cwd() / 'hse_documents'
            self.storage_path.mkdir(exist_ok=True)
        
        def save_export(self, document_id: str, content: bytes, format_type: str, metadata: Dict):
            """Save document to storage"""
            file_path = self.storage_path / f"{document_id}.{format_type}"
            with open(file_path, 'wb') as f:
                f.write(content)
            return str(file_path)
        
        def get_export(self, document_id: str, format_type: str):
            """Get document from storage"""
            file_path = self.storage_path / f"{document_id}.{format_type}"
            if file_path.exists():
                with open(file_path, 'rb') as f:
                    return f.read()
            return None

